static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    Var p("p"), q("q"), r("r");
    Var i("i"), j("j");

    Func init_A("init_A"), init_C4("init_C4");

    // Cast scalar 'np' once into the numeric type used for the arrays.
    Expr np_expr = cast<num_t>(Expr(np));

    // A[i][j][k] = ( (i*j + k) % np ) / np;
    // Mapping: i -> r, j -> q, k -> p  =>  A(p, q, r)
    init_A(p, q, r) =
        cast<num_t>((r * q + p) % np) / np_expr;

    // C4[i][j] = ( (i*j) % np ) / np;
    // Mapping: i -> j (second index), j -> i (first index) => C4(first=j, second=i)
    init_C4(i, j) =
        cast<num_t>((j * i) % np) / np_expr;

    // -------------------------------------------------------------------------
    // Scheduling for initialization
    // -------------------------------------------------------------------------
    // Use moderate vector width; can be tuned for a given machine.
    constexpr int INIT_VEC_WIDTH = 8;

    // Initialize A in parallel over (q, r) and vectorize over p (contiguous dim).
    {
        Var qr_fused("qr_fused"), po("po"), pi("pi");
        init_A
            .fuse(q, r, qr_fused)          // combine q and r for more parallel tasks
            .split(p, po, pi, INIT_VEC_WIDTH)
            .reorder(pi, po, qr_fused)     // pi innermost (vectorized), then po, then fused (outer/parallel)
            .vectorize(pi)
            .parallel(qr_fused);
    }

    // Initialize C4: rows are contiguous in i (dim 0), so vectorize i and parallelize over j.
    {
        Var io("io"), ii("ii");
        init_C4
            .split(i, io, ii, INIT_VEC_WIDTH)
            .reorder(ii, io, j)            // ii innermost (vectorized), then io, then j
            .vectorize(ii)
            .parallel(j);
    }

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem size (from doitgen.hpp / PolyBench)
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers corresponding to:
    //   A[NR][NQ][NP] -> A(np, nq, nr)  (p, q, r)
    //   C4[NP][NP]    -> C4(np, np)
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A, C4);

    // ImageParams for Halide pipeline
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars and RDom
    Var p("p"), q("q"), r("r");
    // Sum over 's' corresponds to the inner-most loop over NP in the original C
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    doitgen(p, q, r) = cast<num_t>(0);
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // -------------------------------------------------------------------------
    // Scheduling for the main kernel
    // -------------------------------------------------------------------------
    //
    // Goal:
    //   - Parallelize over (r, q) to use many cores.
    //   - Vectorize over p, which is the innermost (contiguous) dimension
    //     for both the output and C4.
    //
    // Memory layout:
    //   A_param(s, q, r): 's' is dim 0 (contiguous) for each fixed (q,r).
    //   C4_param(p, s):   'p' is dim 0 (contiguous) for each fixed s.
    //
    // With vectorization over p, Halide will:
    //   - Load A_param(s, q, r) as a scalar and broadcast across the vector.
    //   - Load C4_param(p, s) as a contiguous vector along p.
    //
    // We also fuse r and q into a single parallel loop to generate many tasks.

    // Tunable parameters:
    // Vector width along p (contiguous dim). Adjust for hardware if desired.
    constexpr int VEC_WIDTH = 8;

    Var rq_fused("rq_fused"), p_outer("p_outer"), p_inner("p_inner");

    // Schedule the pure definition (initialization to zero).
    doitgen
        // Combine (r, q) into a single dimension to parallelize across all (r, q) pairs.
        .fuse(r, q, rq_fused)
        // Split p into [p_outer][p_inner] so we can vectorize p_inner.
        .split(p, p_outer, p_inner, VEC_WIDTH)
        // Make p_inner innermost (vectorized), then p_outer, then fused (parallel) dim.
        .reorder(p_inner, p_outer, rq_fused)
        .vectorize(p_inner)
        .parallel(rq_fused);

    // Schedule the reduction update step.
    doitgen.update()
        .fuse(r, q, rq_fused)
        .split(p, p_outer, p_inner, VEC_WIDTH)
        // Loop order (outermost -> innermost):
        //   rq_fused (parallel over all (r,q))
        //   p_outer
        //   s (reduction dim)
        //   p_inner (vectorized)
        //
        // Passing vars from innermost to outermost in reorder():
        .reorder(p_inner, s, p_outer, rq_fused)
        .vectorize(p_inner)
        .parallel(rq_fused);

    // Bind JIT and compile (uses host target by default)
    doitgen.compile_jit();

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
