    int np = NP;

    // Buffers corresponding to:
    //   A[NR][NQ][NP] -> A(np, nq, nr)  (p, q, r)
    //   C4[NP][NP]    -> C4(np, np)
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A, C4);

    // ImageParams for Halide pipeline
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars and RDom
    Var p("p"), q("q"), r("r");
    // Sum over 's' corresponds to the inner-most loop over NP
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    // Explicit reduction form so we can schedule init and update separately.
    doitgen(p, q, r) = cast<num_t>(0);
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // ---------------------------------
    // Scheduling for the Doitgen kernel
    // ---------------------------------
    // We want:
    //   - Good cache locality on the contiguous p-dimension.
    //   - Parallelism across the independent (r, q) pairs.
    //   - Vectorization across p.
    //
    // Memory layout:
    //   A_param(s, q, r): s is the contiguous dimension.
    //   C4_param(p, s)  : p is the contiguous dimension.
    //
    // Vectorizing across p lets us:
    //   - Load/store A_out(p, q, r) in vectors.
    //   - Load C4(p, s) as a contiguous vector for each s.
    //
    // We also fuse r and q into a single loop variable to parallelize
    // across all (r, q) pairs without nested parallelism.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var rq("rq");  // fused (r, q)

    // Make the reduction computed at root to have a single clear loop nest.
    doitgen.compute_root();

    // Schedule the pure definition (initialization to zero).
    doitgen
        .fuse(r, q, rq)      // combine r and q
        .parallel(rq)        // parallelize across all (r, q) pairs
        .vectorize(p, vec_width); // vectorize along contiguous p

    // Schedule the reduction (update) step identically for consistency.
    doitgen.update()
        .parallel(rq)
        .vectorize(p, vec_width);

    // Bind JIT and compile with the chosen target
    doitgen.compile_jit(target);

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
            for (int q_idx = 0; q_idx < nq; q_idx++) {
                for (int p_idx = 0; p_idx < np; p_idx++) {
                    // Mapping back to A[r][q][p] -> A_out(p, q, r)
                    std::cerr << A_out(p_idx, q_idx, r_idx) << '\n';
                }
            }
        }
    }

    // Print kernel execution time in seconds, with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
