#include "doitgen.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and C4 with the same values as the original C code.
 *
 * Original C layout:
 *   A[NR][NQ][NP]  accessed as A[i][j][k]
 *   C4[NP][NP]     accessed as C4[i][j]
 *
 * Halide layout:
 *   A(p, q, r)  with Buffer size (NP, NQ, NR)
 *     mapping: A(p, q, r) == A_c[r][q][p]
 *
 *   C4(p, s) with Buffer size (NP, NP)
 *     mapping: C4(p, s) == C4_c[s][p]
 */
static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    Var p("p"), q("q"), r("r");
    Var i("i"), j("j");

    Func init_A("init_A"), init_C4("init_C4");

    // A[i][j][k] = ( (i*j + k) % np ) / np;
    // Mapping: i -> r, j -> q, k -> p  =>  A(p, q, r)
    init_A(p, q, r) =
        cast<num_t>(((r * q + p) % np)) / cast<int>(np);

    // C4[i][j] = ( (i*j) % np ) / np;
    // Mapping: i -> j (second index), j -> i (first index) => C4(first=j, second=i)
    init_C4(i, j) =
        cast<num_t>(((j * i) % np)) / cast<int>(np);

    // ------------------------------------------------------------
    // Schedule for initialization
    // ------------------------------------------------------------
    // Initialization is cheaper than the main kernel but still O(NR*NQ*NP + NP*NP),
    // so we give it a simple parallel + vector schedule to avoid it dominating
    // runtime for small problem sizes.

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // A is laid out as A(p, q, r) with p contiguous in memory.
    // Parallelize across 'r' (outermost) and vectorize across 'p' (innermost).
    init_A
        .compute_root()
        .parallel(r)
        .vectorize(p, vec_width);

    // C4(i, j) has i as the innermost dimension; do the same pattern.
    init_C4
        .compute_root()
        .parallel(j)
        .vectorize(i, vec_width);

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem size (from doitgen.hpp / PolyBench)
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers corresponding to:
    //   A[NR][NQ][NP] -> A(np, nq, nr)  (p, q, r)
    //   C4[NP][NP]    -> C4(np, np)
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A, C4);

    // ImageParams for Halide pipeline
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars and RDom
    Var p("p"), q("q"), r("r");
    // Sum over 's' corresponds to the inner-most loop over NP
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // ------------------------------------------------------------------
    // Main computation:
    //
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    //
    // To improve locality for the reduction, we introduce a transposed
    // view of C4 so that the reduction variable 's' is the innermost
    // (stride-1) dimension when loading C4.
    // ------------------------------------------------------------------

    // C4_t(s, p) = C4_param(p, s)  (so C4_t has 's' as contiguous dim)
    Func C4_t("C4_t");
    Var si("si"), pi("pi");
    C4_t(si, pi) = C4_param(pi, si);

    Func doitgen("doitgen");

    // Pure definition: initialize the reduction result
    doitgen(p, q, r) = cast<num_t>(0);

    // Reduction definition:
    // sum over s: A_param(s, q, r) * C4_t(s, p)
    doitgen(p, q, r) += A_param(s, q, r) * C4_t(s, p);

    // ------------------------------------------------------------------
    // Schedule for doitgen
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // C4_t is small (NP x NP) and read-only; compute it once at root.
    // Access pattern in the main kernel is C4_t(s, p) with 's' in the
    // reduction loop and 'p' vectorized, so we leave the default
    // loop order and just vectorize across 'p'.
    C4_t
        .compute_root()
        .vectorize(pi, vec_width);

    // Compute the entire 3D result at root.
    doitgen.compute_root();

    // Fuse the (r, q) dimensions into a single loop 'rq' so that
    // we can parallelize across all (r, q) planes uniformly.
    Var rq("rq");
    doitgen
        .fuse(r, q, rq)       // rq ranges over nr * nq
        .parallel(rq)         // distribute work across cores
        .vectorize(p, vec_width); // exploit SIMD over contiguous 'p'

    // For the reduction update step we want an efficient loop order:
    //   outer: rq (fused (r,q)), then reduction var 's',
    //   inner: p (vectorized).
    //
    // This means:
    //   for rq:
    //     for s:
    //       for p (vectorized):
    //         accumulate ...
    doitgen.update()
        .reorder(p, s, rq)   // 'p' innermost for SIMD, then 's', then fused (r,q)
        .vectorize(p, vec_width);

    // Bind JIT and compile with the chosen target
    doitgen.compile_jit(target);

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
            for (int q_idx = 0; q_idx < nq; q_idx++) {
                for (int p_idx = 0; p_idx < np; p_idx++) {
                    // Mapping back to A[r][q][p] -> A_out(p, q, r)
                    std::cerr << A_out(p_idx, q_idx, r_idx) << '\n';
